class Solution:
    def countUnivalSubtrees(self, root: 'TreeNode | None') -> int:
        count = 0

        def dfs(node) -> bool:
            nonlocal count
            if not node:
                return True                     # empty subtree does not break uni-value
            left = dfs(node.left)               # always visit both children (post-order)
            right = dfs(node.right)
            if not (left and right):
                return False
            if node.left and node.left.val != node.val:
                return False
            if node.right and node.right.val != node.val:
                return False
            count += 1                          # this subtree is uni-value
            return True

        dfs(root)                               # each node visited once
        return count
